82	func TestRegisterOverlapAndAdjacency(t *testing.T) {
83		b := NewBook()
84		must := func(r RegisterRequest) {
85			t.Helper()
86			if err := b.RegisterVersion(r); err != nil {
87				t.Fatalf("register %+v: %v", r, err)
88			}
89		}
90		must(RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 1, Start: at(0), End: atPtr(10)})
91	
92		// 相邻交接（end == start）允许
93		must(RegisterRequest{ItemID: "seat", VersionID: "v2", UnitPrice: 1, Start: at(10)})
94	
95		overlaps := []RegisterRequest{
96			{ItemID: "seat", VersionID: "x1", UnitPrice: 1, Start: at(5), End: atPtr(15)},
97			{ItemID: "seat", VersionID: "x2", UnitPrice: 1, Start: at(-5), End: atPtr(1)},
98			{ItemID: "seat", VersionID: "x3", UnitPrice: 1, Start: at(5), End: atPtr(6)},
99			{ItemID: "seat", VersionID: "x4", UnitPrice: 1, Start: at(-5), End: atPtr(20)},
100			{ItemID: "seat", VersionID: "x5", UnitPrice: 1, Start: at(9)},
101		}
102		for _, r := range overlaps {
103			if err := b.RegisterVersion(r); !errors.Is(err, ErrOverlap) {
104				t.Fatalf("expected overlap for %+v, got %v", r, err)
105			}
106		}
107		// 重叠失败不留下部分变更
108		views, err := b.ItemVersions("seat")
109		if err != nil {
110			t.Fatal(err)
111		}
112		if len(views) != 2 {
113			t.Fatalf("failed registrations left changes behind: %d versions", len(views))
114		}
115		// 不同费率项互不影响
116		must(RegisterRequest{ItemID: "room", VersionID: "v1", UnitPrice: 1, Start: at(0), End: atPtr(10)})
117	}
