206	func TestReplacementRejected(t *testing.T) {
207		b := NewBook()
208		must := func(r RegisterRequest) {
209			t.Helper()
210			if err := b.RegisterVersion(r); err != nil {
211				t.Fatalf("register %+v: %v", r, err)
212			}
213		}
214		must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 1, Start: at(10), End: atPtr(50)})
215		must(RegisterRequest{ItemID: "room", VersionID: "other", UnitPrice: 1, Start: at(0)})
216	
217		cases := []struct {
218			name string
219			req  RegisterRequest
220			want error
221		}{
222			{"target missing", RegisterRequest{ItemID: "seat", VersionID: "n1", UnitPrice: 1, Start: at(20), Replaces: "nope"}, ErrReplaceTargetNotFound},
223			{"target in another item", RegisterRequest{ItemID: "seat", VersionID: "n2", UnitPrice: 1, Start: at(20), Replaces: "other"}, ErrReplaceTargetWrongItem},
224			{"start not after old start", RegisterRequest{ItemID: "seat", VersionID: "n3", UnitPrice: 1, Start: at(10), Replaces: "old"}, ErrInvalidReplacement},
225			{"start before old start", RegisterRequest{ItemID: "seat", VersionID: "n4", UnitPrice: 1, Start: at(5), Replaces: "old"}, ErrInvalidReplacement},
226			{"start outside effective interval", RegisterRequest{ItemID: "seat", VersionID: "n5", UnitPrice: 1, Start: at(50), Replaces: "old"}, ErrInvalidReplacement},
227		}
228		for _, c := range cases {
229			if err := b.RegisterVersion(c.req); !errors.Is(err, c.want) {
230				t.Fatalf("%s: want %v, got %v", c.name, c.want, err)
231			}
232		}
233	
234		// 与项内其他版本冲突时整次登记被拒绝，旧版本有效区间不变
235		must(RegisterRequest{ItemID: "seat", VersionID: "later", UnitPrice: 1, Start: at(60), End: atPtr(70)})
236		conflict := RegisterRequest{ItemID: "seat", VersionID: "n6", UnitPrice: 1, Start: at(30), End: atPtr(65), Replaces: "old"}
237		if err := b.RegisterVersion(conflict); !errors.Is(err, ErrOverlap) {
238			t.Fatalf("want overlap, got %v", err)
239		}
240		views, err := b.ItemVersions("seat")
241		if err != nil {
242			t.Fatal(err)
243		}
244		for _, v := range views {
245			if v.VersionID == "old" {
246				if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(50)) {
247					t.Fatalf("rejected registration changed old effective interval: %v", v.EffectiveEnd)
248				}
249				if v.SupersededBy != "" {
250					t.Fatalf("rejected registration left superseded-by: %v", v.SupersededBy)
251				}
252			}
253			if v.VersionID == "n6" {
254				t.Fatal("rejected registration left the new version behind")
255			}
256		}
257	
258		// 已被替代的版本当前有效区间已截断，替代窗口随之收窄
259		must(RegisterRequest{ItemID: "seat", VersionID: "mid", UnitPrice: 1, Start: at(20), End: atPtr(60), Replaces: "old"})
260		outsideTruncated := RegisterRequest{ItemID: "seat", VersionID: "n7", UnitPrice: 1, Start: at(25), Replaces: "old"}
261		if err := b.RegisterVersion(outsideTruncated); !errors.Is(err, ErrInvalidReplacement) {
262			t.Fatalf("start beyond truncated interval: %v", err)
263		}
264	}
