266	func TestQuoteConfirmed(t *testing.T) {
267		now, _ := fixedClock(at(5))
268		b := NewBook(WithClock(now))
269		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 150, Start: at(0), End: atPtr(10)}); err != nil {
270			t.Fatal(err)
271		}
272		out, err := b.Quote(QuoteRequest{RequestID: "q1", ItemID: "seat", VersionID: "v1", Quantity: 4})
273		if err != nil {
274			t.Fatal(err)
275		}
276		if !out.Confirmed || out.UnitPrice != 150 || out.Total != 600 {
277			t.Fatalf("unexpected outcome: %+v", out)
278		}
279		if !out.AcceptedAt.Equal(at(5)) {
280			t.Fatalf("acceptance time: %v", out.AcceptedAt)
281		}
282		if out.Reason != ReasonNone {
283			t.Fatalf("reason on confirmed quote: %v", out.Reason)
284		}
285		// 边界：开始时刻含、结束时刻不含
286		if err := b.RegisterVersion(RegisterRequest{ItemID: "edge", VersionID: "v2", UnitPrice: 1, Start: at(5), End: atPtr(6)}); err != nil {
287			t.Fatal(err)
288		}
289		out, _ = b.Quote(QuoteRequest{RequestID: "q2", ItemID: "edge", VersionID: "v2", Quantity: 1})
290		if !out.Confirmed {
291			t.Fatalf("start instant inclusive: %+v", out)
292		}
293	}
