295	func TestQuoteRejections(t *testing.T) {
296		now, _ := fixedClock(at(5))
297		b := NewBook(WithClock(now))
298		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "future", UnitPrice: 1, Start: at(10)}); err != nil {
299			t.Fatal(err)
300		}
301		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "past", UnitPrice: 1, Start: at(0), End: atPtr(5)}); err != nil {
302			t.Fatal(err)
303		}
304		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "live", UnitPrice: math.MaxInt64, Start: at(5), End: atPtr(9)}); err != nil {
305			t.Fatal(err)
306		}
307	
308		cases := []struct {
309			name string
310			req  QuoteRequest
311			want RejectReason
312		}{
313			{"empty id", QuoteRequest{RequestID: "", ItemID: "seat", VersionID: "live", Quantity: 1}, ReasonEmptyRequestID},
314			{"zero quantity", QuoteRequest{RequestID: "r1", ItemID: "seat", VersionID: "live", Quantity: 0}, ReasonInvalidQuantity},
315			{"negative quantity", QuoteRequest{RequestID: "r2", ItemID: "seat", VersionID: "live", Quantity: -3}, ReasonInvalidQuantity},
316			{"version missing", QuoteRequest{RequestID: "r3", ItemID: "seat", VersionID: "nope", Quantity: 1}, ReasonVersionNotFound},
317			{"item missing", QuoteRequest{RequestID: "r4", ItemID: "nope", VersionID: "v", Quantity: 1}, ReasonVersionNotFound},
318			{"not yet effective", QuoteRequest{RequestID: "r5", ItemID: "seat", VersionID: "future", Quantity: 1}, ReasonVersionNotYetEffective},
319			{"expired", QuoteRequest{RequestID: "r6", ItemID: "seat", VersionID: "past", Quantity: 1}, ReasonVersionExpired},
320			{"overflow", QuoteRequest{RequestID: "r7", ItemID: "seat", VersionID: "live", Quantity: 2}, ReasonTotalOverflow},
321		}
322		for _, c := range cases {
323			out, err := b.Quote(c.req)
324			if err != nil {
325				t.Fatalf("%s: %v", c.name, err)
326			}
327			if out.Confirmed || out.Reason != c.want {
328				t.Fatalf("%s: want reason %v, got %+v", c.name, c.want, out)
329			}
330		}
331		// 空标识的拒绝无法保存、也不应出现在查询中
332		if _, err := b.Lookup(""); !errors.Is(err, ErrRequestNotFound) {
333			t.Fatalf("empty id lookup: %v", err)
334		}
335		// 恰好等于上限时不溢出
336		out, _ := b.Quote(QuoteRequest{RequestID: "r8", ItemID: "seat", VersionID: "live", Quantity: 1})
337		if !out.Confirmed || out.Total != math.MaxInt64 {
338			t.Fatalf("max int64 total: %+v", out)
339		}
340	}
