342	func TestQuoteNoVersionSwitching(t *testing.T) {
343		now, _ := fixedClock(at(5))
344		b := NewBook(WithClock(now))
345		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "expired", UnitPrice: 1, Start: at(0), End: atPtr(4)}); err != nil {
346			t.Fatal(err)
347		}
348		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "live", UnitPrice: 1, Start: at(4)}); err != nil {
349			t.Fatal(err)
350		}
351		out, _ := b.Quote(QuoteRequest{RequestID: "q", ItemID: "seat", VersionID: "expired", Quantity: 1})
352		if out.Confirmed || out.Reason != ReasonVersionExpired {
353			t.Fatalf("must not fall back to another version: %+v", out)
354		}
355	}
