357	func TestConfirmedRecordSurvivesRateChanges(t *testing.T) {
358		now, setNow := fixedClock(at(5))
359		b := NewBook(WithClock(now))
360		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 100, Start: at(0), End: atPtr(10)}); err != nil {
361			t.Fatal(err)
362		}
363		first, err := b.Quote(QuoteRequest{RequestID: "q1", ItemID: "seat", VersionID: "v1", Quantity: 3})
364		if err != nil || !first.Confirmed {
365			t.Fatalf("quote: %v %+v", err, first)
366		}
367	
368		// 版本被替代、随后到期，确认记录不变
369		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "v2", UnitPrice: 999, Start: at(6), Replaces: "v1"}); err != nil {
370			t.Fatal(err)
371		}
372		setNow(at(20))
373		got, err := b.Lookup("q1")
374		if err != nil {
375			t.Fatal(err)
376		}
377		if got != first {
378			t.Fatalf("confirmed record changed: %+v -> %+v", first, got)
379		}
380		// 此刻 v1 已失效，新报价被拒绝，但旧确认仍可查
381		out, _ := b.Quote(QuoteRequest{RequestID: "q2", ItemID: "seat", VersionID: "v1", Quantity: 3})
382		if out.Confirmed || out.Reason != ReasonVersionExpired {
383			t.Fatalf("expected expired: %+v", out)
384		}
385	}
