433	func TestRequestIDConflict(t *testing.T) {
434		now, _ := fixedClock(at(5))
435		b := NewBook(WithClock(now))
436		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 1, Start: at(0)}); err != nil {
437			t.Fatal(err)
438		}
439		first, _ := b.Quote(QuoteRequest{RequestID: "id", ItemID: "seat", VersionID: "v1", Quantity: 1})
440	
441		conflicts := []QuoteRequest{
442			{RequestID: "id", ItemID: "other", VersionID: "v1", Quantity: 1},
443			{RequestID: "id", ItemID: "seat", VersionID: "v2", Quantity: 1},
444			{RequestID: "id", ItemID: "seat", VersionID: "v1", Quantity: 2},
445		}
446		for _, req := range conflicts {
447			if _, err := b.Quote(req); !errors.Is(err, ErrRequestIDConflict) {
448				t.Fatalf("want conflict for %+v", req)
449			}
450		}
451		// 首次记录未被覆盖
452		got, err := b.Lookup("id")
453		if err != nil || got != first {
454			t.Fatalf("first record overwritten: %+v (%v)", got, err)
455		}
456	}
